package org.traccar.protocol;

import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import org.junit.Assert;
import org.junit.Test;
import org.traccar.model.Position;

import java.nio.charset.StandardCharsets;
import java.util.TimeZone;

public class Gt06ProtocolDecoderTest {

    private Gt06ProtocolDecoder decoder = new Gt06ProtocolDecoder(new Gt06Protocol());

    @Test
    public void decodeGpsNoLengthTest() {
        ByteBuf buf = Unpooled.copiedBuffer("69dc035bf0".getBytes(StandardCharsets.UTF_8));
        Position position = new Position();
        Assert.assertTrue(Gt06ProtocolDecoder.decodeGps(position, buf, false, TimeZone.getDefault()));
    }

    @Test
    public void decodeGpsWithLengthTest() {
        ByteBuf buf = Unpooled.copiedBuffer("69dc035bf0".getBytes(StandardCharsets.UTF_8));
        Position position = new Position();
        Assert.assertFalse(Gt06ProtocolDecoder.decodeGps(position, buf, true, TimeZone.getDefault()));
    }

    @Test
    public void decodeGpsWithLengthSatellitesTest() {
        ByteBuf buf = Unpooled.copiedBuffer("69dc035bf0".getBytes(StandardCharsets.UTF_8));
        Position position = new Position();
        Assert.assertTrue(Gt06ProtocolDecoder.decodeGps(position, buf, true, true, false, TimeZone.getDefault()));
    }

    @Test
    public void decodeGpsWithLengthSpeedTest() {
        ByteBuf buf = Unpooled.copiedBuffer("69dc035bf0".getBytes(StandardCharsets.UTF_8));
        Position position = new Position();
        Assert.assertFalse(Gt06ProtocolDecoder.decodeGps(position, buf, true, false, true, TimeZone.getDefault()));
    }

    @Test
    public void decodeGpsWithLengthSatellitesSpeedTest() {
        ByteBuf buf = Unpooled.copiedBuffer("69dc035bf0".getBytes(StandardCharsets.UTF_8));
        Position position = new Position();
        Assert.assertTrue(Gt06ProtocolDecoder.decodeGps(position, buf, true, true, true, TimeZone.getDefault()));
    }

    @Test(expected = Exception.class)
    public void decodeInvalidMessageTest() throws Exception {
        decoder.decode(null, null, "Invalid Message");
    }
}
